package ch.bob.degirocompanion
/** Closed vocabulary: unknown strings never leave the device. */
internal object PhoneDiagnosticPolicy {
    private val allowed=setOf("LIST_TOP_RESULTS_MISSING","LIST_TOP_RESULTS_OVERFLOW","LIST_TOP_RESULTS_INCOMPLETE","KEYBOARD_HIDE_FAILED","LIST_IMAGES_DELIVERED","LIST_FIRST_CAPTURED","LIST_UPLOAD_FAILED","LIST_SCROLL_UNAVAILABLE","LIST_SCROLL_REJECTED","LIST_SCROLL_NO_PROGRESS","LIST_CAPTURE_FAILED","LIST_CAPTURE_ANDROID_VERSION","LIST_CAPTURE_SEARCH_MISSING","LIST_CAPTURE_BOUNDS","LIST_CAPTURE_WINDOW_CHANGED","SEARCH_NO_PROGRESS","SEARCH_TRANSITION_PENDING","SEARCH_RETRY_PARENT","COMPLETE","IDENTITY_CHANGED","INVALID_QUOTES","INVALID_VIEW","NAVIGATION_REJECTED","NONE","NO_QUOTES","OTHER","PARTIAL","PROTECTED_LOGIN","PROTECTED_ORDER","PROTECTED_ORDER_CONFIRM","PROTECTED_ORDER_TYPE","PROTECTED_ORDER_PRICE","PROTECTED_ORDER_QUANTITY","PROTECTED_PASSWORD","PROTECTED_SENSITIVE_CONTENT","PROTECTED_SENSITIVE_INPUT","PROTECTED_VIEW","READ_TIMEOUT","RESULT_MISSING","RETURN_FAILED","RUN_TIMEOUT","SCREEN_LOCKED","SCROLL_LAYOUT_CHANGED","SCROLL_LIMIT","SEARCH_AMBIGUOUS","SEARCH_MISSING","GOLD_IDENTITIES_MISSING","SEARCH_TREE_EMPTY","SEARCH_NOT_ACTIONABLE","SEEK_LIMIT","SERVICE_INTERRUPTED","STOPPED","STORAGE_ERROR","TRANSFER_ERROR","UNRECOGNIZED_INPUT","UNSAFE_VIEW","USER_INTERRUPTED","USER_STOP")
    fun code(value:String):String=if(value in allowed)value else "OTHER"
}
